# TypeScript Avançado - Tipos Utilitários e Pattern Matching

Exploro técnicas avançadas de TypeScript que uso para criar APIs type-safe e expressivas.

## Tipos Condicionais e Mapeados

### Extração de Tipos de Funções

```typescript
// Extrair tipos de parâmetros e retorno
type ExtractParams<T> = T extends (...args: infer P) => any ? P : never
type ExtractReturn<T> = T extends (...args: any[]) => infer R ? R : never

// Exemplo de uso
const apiCall = (id: string, options: { cache: boolean }) => 
  Promise.resolve({ id, name: 'André' })

type ApiParams = ExtractParams<typeof apiCall> // [string, { cache: boolean }]
type ApiReturn = ExtractReturn<typeof apiCall>  // Promise<{ id: string, name: string }>
```

### Builder Pattern Type-Safe

```typescript
type QueryBuilder<T extends Record<string, any> = {}> = {
  select<K extends string>(
    fields: K[]
  ): QueryBuilder<T & { select: K[] }>

  where<K extends keyof any>(
    field: K,
    value: any
  ): QueryBuilder<T & { where: Record<K, any> }>

  orderBy<K extends keyof any>(
    field: K,
    direction: 'asc' | 'desc'
  ): QueryBuilder<T & { orderBy: { field: K, direction: 'asc' | 'desc' } }>

  build(): T extends { select: any } 
    ? T extends { where: any }
      ? 'CompleteQuery'
      : 'MissingWhere'
    : 'MissingSelect'
}

// Uso
const query = createQueryBuilder()
  .select(['name', 'email'])
  .where('active', true)
  .orderBy('createdAt', 'desc')
  .build() // Tipo: 'CompleteQuery'
```

### Validação de Schema em Compile-Time

```typescript
// Definir estrutura de schema
type Schema = {
  name: { type: 'string', required: true }
  age: { type: 'number', required: false }
  email: { type: 'string', required: true }
}

// Converter schema para tipos TypeScript
type InferType<T extends Record<string, any>> = {
  [K in keyof T]: T[K] extends { type: 'string', required: true }
    ? string
    : T[K] extends { type: 'string', required: false }
    ? string | undefined
    : T[K] extends { type: 'number', required: true }
    ? number
    : T[K] extends { type: 'number', required: false }
    ? number | undefined
    : never
}

type User = InferType<Schema>
// Resultado: { name: string, age: number | undefined, email: string }

// Validador em runtime
const createValidator = <T extends Record<string, any>>(schema: T) => {
  return (data: unknown): data is InferType<T> => {
    // Lógica de validação
    return Object.entries(schema).every(([key, config]) => {
      const value = (data as any)?.[key]

      if (config.required && (value === undefined || value === null)) {
        return false
      }

      if (value !== undefined && typeof value !== config.type) {
        return false
      }

      return true
    })
  }
}

const validateUser = createValidator({
  name: { type: 'string' as const, required: true as const },
  age: { type: 'number' as const, required: false as const },
  email: { type: 'string' as const, required: true as const }
})
```

## Pattern Matching com Discriminated Unions

### Result Type para Error Handling

```typescript
type Result<T, E = Error> = 
  | { success: true, data: T }
  | { success: false, error: E }

// Helper para criar resultados
const Ok = <T>(data: T): Result<T> => ({ success: true, data })
const Err = <E>(error: E): Result<never, E> => ({ success: false, error })

// Pattern matching function
const match = <T, E, R>(
  result: Result<T, E>,
  handlers: {
    ok: (data: T) => R
    err: (error: E) => R
  }
): R => {
  if (result.success) {
    return handlers.ok(result.data)
  }
  return handlers.err(result.error)
}

// Exemplo de uso
const fetchUser = async (id: string): Promise<Result<User, string>> => {
  try {
    const response = await fetch(`/api/users/${id}`)
    if (!response.ok) {
      return Err(`HTTP Error: ${response.status}`)
    }
    const user = await response.json()
    return Ok(user)
  } catch (error) {
    return Err(error instanceof Error ? error.message : 'Unknown error')
  }
}

// Usage com pattern matching
const handleUserFetch = async (userId: string) => {
  const result = await fetchUser(userId)

  return match(result, {
    ok: (user) => `Usuário: ${user.name}`,
    err: (error) => `Erro ao buscar usuário: ${error}`
  })
}
```

### State Machine Types

```typescript
// Definir estados da máquina
type LoadingState = { status: 'loading' }
type SuccessState<T> = { status: 'success', data: T }
type ErrorState = { status: 'error', error: string }
type IdleState = { status: 'idle' }

type AsyncState<T> = LoadingState | SuccessState<T> | ErrorState | IdleState

// Actions para transições
type AsyncAction<T> = 
  | { type: 'FETCH_START' }
  | { type: 'FETCH_SUCCESS', payload: T }
  | { type: 'FETCH_ERROR', payload: string }
  | { type: 'RESET' }

// Reducer type-safe
const createAsyncReducer = <T>() => {
  return (state: AsyncState<T>, action: AsyncAction<T>): AsyncState<T> => {
    switch (action.type) {
      case 'FETCH_START':
        return { status: 'loading' }
      case 'FETCH_SUCCESS':
        return { status: 'success', data: action.payload }
      case 'FETCH_ERROR':
        return { status: 'error', error: action.payload }
      case 'RESET':
        return { status: 'idle' }
      default:
        return state
    }
  }
}

// Hook customizado
const useAsyncState = <T>(initialState: AsyncState<T> = { status: 'idle' }) => {
  const [state, dispatch] = useReducer(createAsyncReducer<T>(), initialState)

  const execute = useCallback(async (asyncFn: () => Promise<T>) => {
    dispatch({ type: 'FETCH_START' })
    try {
      const result = await asyncFn()
      dispatch({ type: 'FETCH_SUCCESS', payload: result })
    } catch (error) {
      dispatch({ 
        type: 'FETCH_ERROR', 
        payload: error instanceof Error ? error.message : 'Unknown error'
      })
    }
  }, [])

  return { state, execute, reset: () => dispatch({ type: 'RESET' }) }
}
```

## Branded Types para Type Safety

```typescript
// Criar tipos com "marca" para evitar mixing
type Brand<T, K> = T & { __brand: K }

type UserId = Brand<string, 'UserId'>
type Email = Brand<string, 'Email'>
type UUID = Brand<string, 'UUID'>

// Funções para criar branded types
const createUserId = (id: string): UserId => {
  if (!id.startsWith('user_')) {
    throw new Error('Invalid user ID format')
  }
  return id as UserId
}

const createEmail = (email: string): Email => {
  if (!email.includes('@')) {
    throw new Error('Invalid email format')
  }
  return email as Email
}

// Uso impossibilita mixing acidental
const getUserProfile = (userId: UserId, email: Email) => {
  // Implementação
}

// Isso compilaria sem branded types, mas causaria erro lógico
// getUserProfile('some-email@example.com', 'user_123') // ❌ Prevented by types
getUserProfile(createUserId('user_123'), createEmail('test@example.com')) // ✅
```

## Template Literal Types

```typescript
// Gerar tipos baseados em strings
type Route = '/users' | '/products' | '/orders'
type Method = 'GET' | 'POST' | 'PUT' | 'DELETE'

// Combinar em todas as possibilidades
type ApiEndpoint = `${Method} ${Route}`
// 'GET /users' | 'POST /users' | 'PUT /users' | ... etc

// CSS-in-JS type-safe
type CSSUnit = 'px' | 'em' | 'rem' | '%' | 'vh' | 'vw'
type Size<T extends number> = `${T}${CSSUnit}`

const createStyle = <T extends number>(size: T, unit: CSSUnit): Size<T> => {
  return `${size}${unit}` as Size<T>
}

const margin = createStyle(16, 'px') // Type: "16px"

// SQL Query Builder com template literals
type SQLOperator = '=' | '>' | '<' | '>=' | '<=' | 'LIKE' | 'IN'
type WhereClause<T extends string> = `${T} ${SQLOperator} ?`

const buildWhere = <T extends string>(field: T, operator: SQLOperator): WhereClause<T> => {
  return `${field} ${operator} ?` as WhereClause<T>
}

const whereClause = buildWhere('name', 'LIKE') // Type: "name LIKE ?"
```

## Higher-Order Types

```typescript
// Compose types como funções
type Compose<F, G> = F extends (arg: infer A) => infer B
  ? G extends (arg: B) => infer C
    ? (arg: A) => C
    : never
  : never

// Pipe para transformações sequenciais
type Pipe<T, Fns extends readonly any[]> = Fns extends readonly []
  ? T
  : Fns extends readonly [infer F, ...infer Rest]
    ? F extends (arg: T) => infer R
      ? Pipe<R, Rest>
      : never
    : never

// Exemplo de uso
type StringToNumber = (s: string) => number
type NumberToBoolean = (n: number) => boolean

type StringToBoolean = Compose<StringToNumber, NumberToBoolean>
// (s: string) => boolean

// Implementação runtime
const pipe = <T, R>(value: T, ...fns: Array<(arg: any) => any>): R => {
  return fns.reduce((acc, fn) => fn(acc), value) as R
}

const result = pipe(
  '42',
  (s: string) => parseInt(s),
  (n: number) => n > 0,
  (b: boolean) => b ? 'positive' : 'negative'
) // Type inferred correctly
```

Estas técnicas avançadas de TypeScript permitem criar APIs mais expressivas e catches de erros em tempo de compilação que economizam horas de debug.

