// Create "branded" types to prevent mixing
type Brand<T, K> = T & { __brand: K }

type UserId = Brand<string, 'UserId'>
type Email = Brand<string, 'Email'>
type UUID = Brand<string, 'UUID'>

// Functions to create branded types
const createUserId = (id: string): UserId => {
  if (!id.startsWith('user_')) {
    throw new Error('Invalid user ID format')
  }
  return id as UserId
}

const createEmail = (email: string): Email => {
  if (!email.includes('@')) {
    throw new Error('Invalid email format')
  }
  return email as Email
}

// Usage prevents accidental mixing
const getUserProfile = (userId: UserId, email: Email) => {
  // Implementation
}

// This would compile without branded types, but cause logical error
// getUserProfile('some-email@example.com', 'user_123') // ❌ Prevented by types
getUserProfile(createUserId('user_123'), createEmail('test@example.com')) // ✅
```

## Template Literal Types

```typescript
// Generate string-based types
type Route = '/users' | '/products' | '/orders'
type Method = 'GET' | 'POST' | 'PUT' | 'DELETE'

// Combine into all possibilities
type ApiEndpoint = `${Method} ${Route}`
// 'GET /users' | 'POST /users' | 'PUT /users' | ... etc

// Type-safe CSS-in-JS
type CSSUnit = 'px' | 'em' | 'rem' | '%' | 'vh' | 'vw'
type Size<T extends number> = `${T}${CSSUnit}`

const createStyle = <T extends number>(size: T, unit: CSSUnit): Size<T> => {
  return `${size}${unit}` as Size<T>
}

const margin = createStyle(16, 'px') // Type: "16px"

// SQL Query Builder with template literals
type SQLOperator = '=' | '>' | '<' | '>=' | '<=' | 'LIKE' | 'IN'
type WhereClause<T extends string> = `${T} ${SQLOperator} ?`

const buildWhere = <T extends string>(field: T, operator: SQLOperator): WhereClause<T> => {
  return `${field} ${operator} ?` as WhereClause<T>
}

const whereClause = buildWhere('name', 'LIKE') // Type: "name LIKE ?"
```

## Higher-Order Types

```typescript
// Compose types like functions
type Compose<F, G> = F extends (arg: infer A) => infer B
  ? G extends (arg: B) => infer C
    ? (arg: A) => C
    : never
  : never

// Pipe for sequential transformations
type Pipe<T, Fns extends readonly any[]> = Fns extends readonly []
  ? T
  : Fns extends readonly [infer F, ...infer Rest]
    ? F extends (arg: T) => infer R
      ? Pipe<R, Rest>
      : never
    : never

// Usage example
type StringToNumber = (s: string) => number
type NumberToBoolean = (n: number) => boolean

type StringToBoolean = Compose<StringToNumber, NumberToBoolean>
// (s: string) => boolean

// Runtime implementation
const pipe = <T, R>(value: T, ...fns: Array<(arg: any) => any>): R => {
  return fns.reduce((acc, fn) => fn(acc), value) as R
}

const result = pipe(
  '42',
  (s: string) => parseInt(s),
  (n: number) => n > 0,
  (b: boolean) => b ? 'positive' : 'negative'
) // Type inferred correctly
```

